// SLIDING WINDOW: Best time to buy and sell stock (Kadane's variant)
// Finance: find max profit from daily stock prices
package com.bank.algo.array;

import java.math.BigDecimal;

public class MaxProfitCalculator {

    /**
     * Given daily prices, find max profit from one buy + one sell.
     * Track minimum price seen so far, compute profit at each step.
     * Time: O(n), Space: O(1)
     */
    public BigDecimal maxProfit(BigDecimal[] prices) {
        if (prices == null || prices.length < 2) return BigDecimal.ZERO;

        BigDecimal minPrice = prices[0];
        BigDecimal maxProfit = BigDecimal.ZERO;

        for (int i = 1; i < prices.length; i++) {
            BigDecimal profit = prices[i].subtract(minPrice);
            if (profit.compareTo(maxProfit) > 0) maxProfit = profit;
            if (prices[i].compareTo(minPrice) < 0) minPrice = prices[i];
        }
        return maxProfit;
    }

    /**
     * SLIDING WINDOW: Simple Moving Average (SMA) over k days.
     * Finance: calculate 5-day, 20-day, 50-day moving averages.
     * Time: O(n), Space: O(1)
     */
    public BigDecimal[] movingAverage(BigDecimal[] prices, int k) {
        if (prices.length < k) return new BigDecimal[0];
        BigDecimal[] result = new BigDecimal[prices.length - k + 1];

        BigDecimal windowSum = BigDecimal.ZERO;
        for (int i = 0; i < k; i++) windowSum = windowSum.add(prices[i]);
        result[0] = windowSum.divide(BigDecimal.valueOf(k), 2, java.math.RoundingMode.HALF_UP);

        for (int i = k; i < prices.length; i++) {
            windowSum = windowSum.add(prices[i]).subtract(prices[i - k]);
            result[i - k + 1] = windowSum.divide(BigDecimal.valueOf(k), 2, java.math.RoundingMode.HALF_UP);
        }
        return result;
    }
}
