// HASHMAP: Find two trades that sum to a target settlement amount
// Time: O(n), Space: O(n)
package com.bank.algo.array;

import java.util.*;

public class TwoSumFinder {

    public int[] findTwoTradesForSettlement(int[] amounts, int target) {
        Map<Integer, Integer> seen = new HashMap<>();
        for (int i = 0; i < amounts.length; i++) {
            int complement = target - amounts[i];
            if (seen.containsKey(complement)) {
                return new int[]{seen.get(complement), i};
            }
            seen.put(amounts[i], i);
        }
        return new int[]{};  // no pair found
    }
}
