// DYNAMIC PROGRAMMING: Minimum number of notes/coins for a withdrawal amount
// Finance: ATM dispenses minimum denominations
// Time: O(amount × denominations), Space: O(amount)
package com.bank.algo.dp;

import java.util.Arrays;

public class CoinChangeForDenominations {

    public int minDenominations(int[] denominations, int amount) {
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, amount + 1);
        dp[0] = 0;

        for (int i = 1; i <= amount; i++) {
            for (int denom : denominations) {
                if (denom <= i) {
                    dp[i] = Math.min(dp[i], dp[i - denom] + 1);
                }
            }
        }
        return dp[amount] > amount ? -1 : dp[amount];
    }
}
