// DFS: Detect circular transfers (A→B→C→A) in transaction graph
// Finance: fraud detection — circular money laundering
// Time: O(V+E)
package com.bank.algo.graph;

import java.util.*;

public class TransactionCycleDetector {

    public boolean hasCycle(Map<String, List<String>> transferGraph) {
        Set<String> visited = new HashSet<>();
        Set<String> inStack = new HashSet<>();  // recursion stack — detects back-edge

        for (String account : transferGraph.keySet()) {
            if (dfs(account, transferGraph, visited, inStack)) return true;
        }
        return false;
    }

    private boolean dfs(String node, Map<String, List<String>> graph,
                         Set<String> visited, Set<String> inStack) {
        if (inStack.contains(node)) return true;   // back-edge → cycle!
        if (visited.contains(node)) return false;

        visited.add(node);
        inStack.add(node);

        for (String neighbor : graph.getOrDefault(node, List.of())) {
            if (dfs(neighbor, graph, visited, inStack)) return true;
        }

        inStack.remove(node);  // backtrack
        return false;
    }
}
