package com.bank.algo.array;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class MaxProfitCalculatorTest {

    MaxProfitCalculator calc = new MaxProfitCalculator();

    @Test
    void shouldFindMaxProfit() {
        BigDecimal[] prices = {bd("2200"), bd("2350"), bd("2100"), bd("2450"), bd("2400"), bd("2550")};
        assertThat(calc.maxProfit(prices)).isEqualByComparingTo("450"); // buy at 2100, sell at 2550
    }

    @Test
    void shouldReturnZeroForDecreasingPrices() {
        BigDecimal[] prices = {bd("2500"), bd("2400"), bd("2300"), bd("2200")};
        assertThat(calc.maxProfit(prices)).isEqualByComparingTo("0");
    }

    private BigDecimal bd(String val) { return new BigDecimal(val); }
}
